<?php
$pageTitle='Track your move | RoomShift';$pageMeta='View the latest status and audit timeline for your RoomShift booking.';include __DIR__.'/includes/header.php';include __DIR__.'/includes/navbar.php';$result=null;$error='';
if($_SERVER['REQUEST_METHOD']==='GET'&&isset($_GET['code'])){try{require_once dirname(__DIR__).'/backend/repositories/BookingRepository.php';$code=strtoupper(trim((string)$_GET['code']));if(!preg_match('/^[A-F0-9]{16}$/',$code))$error='Enter the tracking code provided when the booking was created.';else{$result=(new BookingRepository(roomshift_db()))->trackByCode($code);if(!$result)$error='No tracking record matches that code.';}}catch(Throwable $e){error_log('[RoomShift tracking page] '.$e->getMessage());$error='Tracking is temporarily unavailable.';}}
?><main class="container section-space"><header class="page-heading"><p class="eyebrow">Move updates</p><h1>Track your booking</h1><p>Your tracking code is private. Only enter it on a device you trust.</p></header><form class="contact-panel mb-4" method="get"><label class="form-label" for="trackingCode">Tracking code</label><div class="input-group"><input class="form-control" id="trackingCode" name="code" pattern="[A-Fa-f0-9]{16}" maxlength="16" required value="<?= e($_GET['code']??'') ?>"><button class="btn btn-gold">Find booking</button></div></form><?php if($error): ?><div class="alert alert-warning" role="status"><?= e($error) ?></div><?php endif; ?><?php if($result): ?><section class="quote-result"><p class="eyebrow">Booking <?= e($result['booking_ref']) ?></p><h2 class="h3"><?= e(ucwords(str_replace('_',' ',$result['status']))) ?></h2><ol class="timeline"><?php foreach($result['history'] as $event): ?><li><time><?= e($event['created_at']) ?></time><strong><?= e(ucwords(str_replace('_',' ',$event['to_status']))) ?></strong><?php if($event['note']): ?><span><?= e($event['note']) ?></span><?php endif; ?></li><?php endforeach; ?></ol></section><?php endif; ?></main><?php include __DIR__.'/includes/footer.php';
